## 4. Verification

The harness checks (1) the deterministic bushy example, (2) a disconnected query, (3) hyperedge support, and (4) 1000 randomized graphs against an independent exhaustive DPsize reference that enumerates every bipartition with cross products allowed and no pruning. A plan's cost is also recomputed from the emitted tree.

`/workspace/verify.js`:

```js
'use strict';

const { makeJoinOrder, bruteForce, planToString } = require('./join_order.js');

let failures = 0;
function assert(cond, msg) {
  if (!cond) { failures++; console.error('FAIL:', msg); }
  else console.log('ok  -', msg);
}
function relClose(a, b, rtol = 1e-6) {
  if (a === b) return true;
  const m = Math.max(Math.abs(a), Math.abs(b));
  return Math.abs(a - b) / m <= rtol;
}

// 1. deterministic example
const example = {
  relations: ['R0', 'R1', 'R2', 'R3'],
  cardinalities: [1000, 1000, 1000, 1000],
  predicates: [
    { relations: [0, 1], selectivity: 0.9 },
    { relations: [1, 2], selectivity: 0.001 },
    { relations: [2, 3], selectivity: 0.9 },
  ],
};
const ex = makeJoinOrder(example);
const exb = bruteForce(example);
console.log('--- deterministic example ---');
console.log(planToString(ex.plan));
console.log('dp cost      =', ex.cost);
console.log('brute cost   =', exb.cost);
console.log('greedy bound =', ex.greedyCost);
console.log('explored     =', ex.explored, ' pruned =', ex.pruned, ' memoized =', ex.memoized);
assert(relClose(ex.cost, exb.cost), 'DP cost equals exhaustive DPsize cost');
assert(relClose(ex.verifiedCost, ex.cost), 'reported cost equals recomputed tree cost');
assert(ex.cost <= ex.greedyCost * (1 + 1e-12), 'DP is never worse than the greedy upper bound');
assert(ex.pruned > 0, 'branch & bound pruned at least one connected candidate');

// 2. disconnected query
const disconnected = {
  relations: ['A', 'B', 'C', 'D'],
  cardinalities: [10, 20, 30, 40],
  predicates: [
    { relations: [0, 1], selectivity: 0.5 },
    { relations: [2, 3], selectivity: 0.5 },
  ],
};
const dc = makeJoinOrder(disconnected);
const dcb = bruteForce(disconnected);
console.log('\n--- disconnected example ---');
console.log(planToString(dc.plan));
assert(relClose(dc.cost, dcb.cost), 'disconnected query: cost equals brute force');
assert(dc.crossUpdates >= 1, 'cross-product candidates were explored during the DP');
assert(dc.connected === false && dc.components === 2, 'query detected as 2 components');
assert(dc.memoized === 15, 'all non-empty subsets memoized exactly once (2^4 - 1)');
let crossCount = 0, joinCount = 0;
(function walk(node) {
  if (!node || node.type === 'rel') return;
  joinCount++;
  if (node.cross) crossCount++;
  walk(node.left); walk(node.right);
})(dc.plan);
assert(joinCount === 3 && crossCount === 1, '4 relations -> 3 joins, 1 of them a cross product');

// 3. hyperedge support
const hyper = {
  relations: ['H0', 'H1', 'H2', 'H3'],
  cardinalities: [100, 100, 100, 1000],
  predicates: [
    { relations: [0, 1, 2], selectivity: 0.001 },
    { relations: [2, 3], selectivity: 0.1 },
  ],
};
const hy = makeJoinOrder(hyper);
const hyb = bruteForce(hyper);
assert(relClose(hy.cost, hyb.cost), 'hyperedge query: cost equals brute force');

// 4. randomized differential testing
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = mulberry32(0xC0FFEE);

let checked = 0, mismatches = 0, maxRel = 0;
for (let t = 0; t < 1000; t++) {
  const n = 2 + Math.floor(rnd() * 6);
  const relations = Array.from({ length: n }, (_, i) => 'R' + i);
  const cardinalities = Array.from({ length: n }, () => 1 + Math.floor(rnd() * 5000));
  const predicates = [];
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      if (rnd() < 0.35) {
        predicates.push({ relations: [i, j], selectivity: 0.001 + rnd() * 0.999 });
      }
    }
  }
  const input = { relations, cardinalities, predicates };
  const dp = makeJoinOrder(input);
  const bf = bruteForce(input);
  checked++;
  const rel = Math.abs(dp.cost - bf.cost) / Math.max(1, Math.abs(bf.cost));
  if (rel > maxRel) maxRel = rel;
  if (rel > 1e-6) {
    mismatches++;
    if (mismatches <= 3) console.error('MISMATCH', JSON.stringify(input), 'dp=', dp.cost, 'brute=', bf.cost);
  }
  if (Math.abs(dp.verifiedCost - dp.cost) > 1e-6 * Math.max(1, Math.abs(dp.cost))) {
    failures++;
    console.error('INCONSISTENT COST', JSON.stringify(input));
  }
}
console.log(`\nrandom differential tests: ${checked} cases, ${mismatches} mismatches, max relative cost diff ${maxRel.toExponential(3)}`);
assert(mismatches === 0, 'optimal cost matches exhaustive DPsize on all random cases (within float rounding)');

console.log('\n=================================');
if (failures === 0) console.log('ALL CHECKS PASSED');
else { console.log(`${failures} CHECK(S) FAILED`); process.exit(1); }
```

